#define PI 3.14159265358979323846

float random (in float x) { return fract(sin(x)*1e4); }
float random (in vec2 _st) { return fract(sin(dot(_st.xy, vec2(12.9898,78.233)))* 43758.5453123);}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = fragCoord/iResolution.xy;
    st.x *= iResolution.x/iResolution.y;

    const float ROWS = 100.0;
    const float COLS = 100.0;

    st *= vec2(COLS,ROWS);
    vec2 ipos = floor(st);
    float index = (ipos.x/COLS)*COLS + ipos.y/ROWS;

    st.y += iTime * 10.0 * random(ipos.x);  // Col animation

    ipos = floor(st);
    float anim = abs(sin(iTime*0.2)-1.)*100.0;
    float rnd = random(ipos);
    rnd = step(random(ipos.x)*1.34,rnd);
    rnd *= step(anim, index);

    vec3 color = vec3(0.15,0.6,0.1);
    color *= vec3(1.0,rnd,1.0);

    fragColor = vec4(color,1.0);
}
